// Des: Wait for the owner when a job truly needs them, then continue by itself
// Flo: needs-you halt > 2nd challenge in 24 h = unsafe > notify (plain line) > touch nothing, poll the page > cleared: settle, re-check, cool pace, resume the same step > deadline: park
// I/O: Ctx + flow id + item id + halt kind (caller) > Outcome (resumed, timeout, unsafe); states and wait time saved in the state db
// ===================================================================
const std = @import("std"); const task = @import("ru-task-runn.zig"); const halt = @import("ru-safe-halt.zig"); const pace = @import("ru-huma-pace.zig"); const flow = @import("ru-flow-runz.zig"); const noti = @import("ru-noti-send.zig");
const CF = .{ .dayz = 86400000, .poll = 3000, .pmin = 100, .unsf = "unsafe_until", .rept = 2 };
pub const Outcome = enum { resumed, timeout, unsafe };
pub fn realMs(iozz: std.Io) i64 { return @intCast(std.Io.Clock.real.now(iozz).toMilliseconds()); }
pub fn instruct(kind: halt.Halt, lang: []const u8) []const u8 { const vi = std.mem.eql(u8, lang, "vi"); return switch (kind) { .checkpoint => if (vi) "fb cần bạn: xác nhận đó là bạn trên Facebook, trong cửa sổ trình duyệt. fb sẽ tự chạy tiếp." else "fb needs you: confirm it is you on Facebook in the browser window. fb continues by itself.", .captcha => if (vi) "fb cần bạn: giải bước kiểm tra bảo mật trong cửa sổ trình duyệt. fb sẽ tự chạy tiếp." else "fb needs you: solve the security check in the browser window. fb continues by itself.", .twofa => if (vi) "fb cần bạn: nhập mã 2FA trong cửa sổ trình duyệt. fb sẽ tự chạy tiếp." else "fb needs you: enter your 2FA code in the browser window. fb continues by itself.", .logout => if (vi) "fb cần bạn: đăng nhập Facebook trong cửa sổ trình duyệt. fb sẽ tự chạy tiếp." else "fb needs you: log in to Facebook in the browser window. fb continues by itself.", .overlay => if (vi) "fb cần bạn: đóng hộp thoại đang mở trong cửa sổ trình duyệt. fb sẽ tự chạy tiếp." else "fb needs you: close the open dialog in the browser window. fb continues by itself.", else => if (vi) "fb cần bạn kiểm tra Facebook." else "fb needs you to check Facebook." }; }
pub fn unsafeText(lang: []const u8) []const u8 { return if (std.mem.eql(u8, lang, "vi")) "fb đã dừng để giữ an toàn cho tài khoản: Facebook đã hạn chế hoặc cảnh báo. Hãy nghỉ 24 giờ." else "fb stopped to keep your account safe: Facebook limited or warned something. Rest for 24 hours."; }
pub fn notify(ctx: *task.Ctx, msg: []const u8) void { _ = noti.send(ctx.gpaz, ctx.iozz, ctx.aren, ctx.conf, ctx.statd, realMs(ctx.iozz), msg); task.say(ctx, "{s}", .{msg}); }
pub fn unsafeUntil(ctx: *task.Ctx) i64 { return ctx.store.metaGet(CF.unsf) catch 0; }
pub fn stopUnsafe(ctx: *task.Ctx, fid: i64) void { ctx.store.metaSet(CF.unsf, realMs(ctx.iozz) + @as(i64, ctx.conf.cool_hour_coun) * 3600000) catch {}; ctx.store.flowSet(fid, "stop") catch {}; task.coolStart(ctx); notify(ctx, unsafeText(ctx.conf.lang_main_code)); }
fn challenges(ctx: *task.Ctx) u32 { const rows = ctx.store.logRecent(ctx.aren, 200) catch return 0; const cut = realMs(ctx.iozz) - CF.dayz; var cnt: u32 = 0; for (rows) |row| { if (row.ts < cut or !std.mem.eql(u8, row.kind, "halt")) continue; if (std.mem.eql(u8, row.what, "checkpoint") or std.mem.eql(u8, row.what, "captcha") or std.mem.eql(u8, row.what, "twofa")) cnt += 1; } return cnt; }
fn freshSame(ctx: *task.Ctx, kind: halt.Halt, now: i64) bool { const rows = ctx.store.logRecent(ctx.aren, 6) catch return false; for (rows) |row| { if (std.mem.eql(u8, row.kind, "halt") and std.mem.eql(u8, row.what, halt.name(kind)) and now - row.ts < 10000) return true; } return false; }
pub fn handleNeeds(ctx: *task.Ctx, fid: i64, item: i64, kind: halt.Halt) !Outcome { const t0 = realMs(ctx.iozz); if (!freshSame(ctx, kind, t0)) ctx.store.logAdd("halt", halt.name(kind), false, t0) catch {}; if ((kind == .checkpoint or kind == .captcha or kind == .twofa) and challenges(ctx) >= CF.rept) { stopUnsafe(ctx, fid); return .unsafe; } try ctx.store.itemSet(item, "wait", halt.name(kind), t0); try ctx.store.flowSet(fid, "wait"); try ctx.store.flowBump(fid, 1, 0); notify(ctx, instruct(kind, ctx.conf.lang_main_code)); const lim: i64 = if (ctx.conf.wait_maxx_secs > 0) @as(i64, ctx.conf.wait_maxx_secs) * 1000 else @as(i64, ctx.conf.wait_maxx_minu) * 60000; const perc = ctx.conf.time_scal_perc; while (true) { ctx.page.arm(ctx.conf.brow_time_seco * 1000); const cur = flow.peekHalt(ctx.page, ctx.aren); if (cur == null) { pace.nap(ctx.iozz, @as(u64, ctx.conf.sett_wait_minu) * 60000, perc); ctx.page.arm(ctx.conf.brow_time_seco * 1000); if (flow.peekHalt(ctx.page, ctx.aren) == null) break; } else if (halt.classOf(cur.?) == .unsafe) { stopUnsafe(ctx, fid); try ctx.store.flowBump(fid, 0, realMs(ctx.iozz) - t0); return .unsafe; } if (realMs(ctx.iozz) - t0 >= lim) { try ctx.store.flowSet(fid, "park"); try ctx.store.flowBump(fid, 0, realMs(ctx.iozz) - t0); notify(ctx, if (std.mem.eql(u8, ctx.conf.lang_main_code, "vi")) "fb đã chờ quá lâu và tạm dừng. Xử lý xong rồi chạy lại: fb flow run." else "fb waited too long and paused. Finish the step, then run: fb flow run."); return .timeout; } const gap: u64 = @max(pace.scaled(CF.poll, perc), CF.pmin); std.Io.sleep(ctx.iozz, .fromMilliseconds(@intCast(gap)), .awake) catch {}; } try ctx.store.flowBump(fid, 0, realMs(ctx.iozz) - t0); try ctx.store.itemSet(item, "todo", "resumed", realMs(ctx.iozz)); try ctx.store.flowSet(fid, "run"); task.coolStart(ctx); return .resumed; }
